import type { KqSocialContentMessage, KqSocialContentPerson } from "./kanab-quest-social-content";
import type { KqSocialNarrative } from "./kanab-quest-social-narrative-types";

type Voice = [KqSocialContentPerson, string];
const m = (person: KqSocialContentPerson, text: string): KqSocialContentMessage => ({ id: "", person, text });
const choice = (
  label: string, description: string, upside: string, downside: string,
  outcome: string, post: string, first: Voice, second: Voice,
): KqSocialNarrative["choices"][string] => ({
  label, description, upside, downside, outcome, post,
  replies: [m(...first), m(...second)],
});
const after = (body: string, voice: Voice, caption?: string): NonNullable<KqSocialNarrative["continuations"]>[string] => ({
  body, comment: m(...voice), ...(caption ? { caption } : {}),
});

